calc.mjs.text:
// Crypto cost-basis lot matcher. Pure functions, no I/O, no dependencies.
//
// Input is a CSV of the user's own transactions. Every row is a buy, an income
// receipt, a sale/spend, or a transfer (ignored). A coin-for-coin swap is entered
// as two rows: a sale of what was given up and a buy of what was received, each at
// its USD value that day. The module matches each disposal to earlier acquisition
// lots under FIFO, LIFO, HIFO, LOFO or a tax-aware greedy rule, splits every
// disposal into Form 8949-style rows with short/long-term holding periods, and
// compares the methods on the chosen tax year. It prices nothing and fetches
// nothing: every figure comes from the rows the user supplies.

export const METHODS = ["FIFO", "LIFO", "HIFO", "LOFO", "TAXMIN"];
export const METHOD_LABELS = {
  FIFO: "First in, first out",
  LIFO: "Last in, first out",
  HIFO: "Highest cost first",
  LOFO: "Lowest cost first",
  TAXMIN: "Tax-aware greedy (lowest tax per coin first)",
};

const EPS = 1e-9;
const cents = (n) => Math.round((n + Number.EPSILON * Math.sign(n)) * 100) / 100;

// ---- CSV ---------------------------------------------------------------

export function parseCsv(text) {
  const src = String(text ?? "").replace(/^﻿/, "");
  const firstLine = src.split(/\r?\n/, 1)[0] || "";
  const delim = firstLine.includes("\t") && !firstLine.includes(",") ? "\t" : ",";
  const rows = [];
  let row = [];
  let cell = "";
  let quoted = false;
  for (let i = 0; i < src.length; i++) {
    const c = src[i];
    if (quoted) {
      if (c === '"') {
        if (src[i + 1] === '"') { cell += '"'; i++; } else quoted = false;
      } else cell += c;
    } else if (c === '"') quoted = true;
    else if (c === delim) { row.push(cell); cell = ""; }
    else if (c === "\n" || c === "\r") {
      if (c === "\r" && src[i + 1] === "\n") i++;
      row.push(cell); cell = "";
      if (row.some((x) => x.trim() !== "")) rows.push(row);
      row = [];
    } else cell += c;
  }
  row.push(cell);
  if (row.some((x) => x.trim() !== "")) rows.push(row);
  return rows.map((r) => r.map((x) => x.trim()));
}

const norm = (s) => String(s).toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();

const HEADER_ALIASES = {
  date: ["date", "time", "timestamp", "datetime", "date utc", "transaction date", "date time", "date and time"],
  type: ["type", "side", "transaction type", "operation", "action", "kind"],
  asset: ["asset", "currency", "coin", "symbol", "token", "ticker", "base asset"],
  quantity: ["quantity", "amount", "qty", "size", "quantity transacted", "units"],
  total: ["total", "total usd", "usd value", "value", "value usd", "proceeds", "subtotal", "total value", "usd"],
  price: ["price", "price per unit", "spot price", "unit price", "price usd", "rate"],
  fee: ["fee", "fees", "fee usd", "fees usd", "commission"],
  wallet: ["wallet", "account", "exchange", "platform", "source"],
  toWallet: ["to wallet", "to account", "to", "destination", "destination wallet", "to exchange"],
};

export function mapHeaders(headerRow) {
  const map = {};
  const names = headerRow.map(norm);
  for (const [field, aliases] of Object.entries(HEADER_ALIASES)) {
    for (const a of aliases) {
      const idx = names.indexOf(a);
      if (idx >= 0) { map[field] = idx; break; }
    }
  }
  return map;
}

const TYPE_WORDS = {
  buy: ["buy", "purchase", "bought", "advanced trade buy", "market buy", "limit buy"],
  income: ["income", "reward", "rewards", "staking", "staking reward", "airdrop", "mining", "interest", "earn", "learning reward", "referral", "payment received"],
  sell: ["sell", "sale", "sold", "spend", "market sell", "limit sell", "advanced trade sell", "payment sent", "convert out"],
  transfer: ["transfer", "send", "receive", "deposit", "withdrawal", "withdraw", "move"],
};

export function normalizeType(raw) {
  const t = norm(raw);
  for (const [kind, words] of Object.entries(TYPE_WORDS)) if (words.includes(t)) return kind;
  return null;
}

export function parseDate(raw) {
  const s = String(raw ?? "").trim();
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:[T\s].*)?$/);
  let y, mo, d;
  if (m) { y = +m[1]; mo = +m[2]; d = +m[3]; }
  else {
    m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})(?:[T\s].*)?$/);
    if (!m) return null;
    mo = +m[1]; d = +m[2]; y = +m[3];
  }
  const dt = new Date(Date.UTC(y, mo - 1, d));
  if (dt.getUTCFullYear() !== y || dt.getUTCMonth() !== mo - 1 || dt.getUTCDate() !== d) return null;
  return dt.toISOString().slice(0, 10);
}

function parseNumber(raw) {
  if (raw === undefined || raw === null) return null;
  const s = String(raw).replace(/[$,\s]/g, "").replace(/^\((.*)\)$/, "-$1");
  if (s === "") return null;
  const n = Number(s);
  return Number.isFinite(n) ? n : NaN;
}

// ---- rows --------------------------------------------------------------

// Returns { transactions, skipped, errors }. A transaction is
// { line, date, kind: 'buy'|'income'|'sell', asset, qty, usd, fee, wallet }.
export function parseTransactions(text) {
  const grid = parseCsv(text);
  const out = { transactions: [], skipped: [], errors: [] };
  if (grid.length === 0) return out;
  const map = mapHeaders(grid[0]);
  const missing = ["date", "type", "asset", "quantity"].filter((f) => map[f] === undefined);
  if (map.total === undefined && map.price === undefined) missing.push("total or price");
  if (missing.length) {
    out.errors.push(`Header row is missing: ${missing.join(", ")}. Expected columns like date, type, asset, quantity, total (USD), fee, wallet.`);
    return out;
  }
  for (let i = 1; i < grid.length; i++) {
    const r = grid[i];
    const line = i + 1;
    const get = (f) => (map[f] === undefined ? "" : (r[map[f]] ?? ""));
    const kind = normalizeType(get("type"));
    if (kind === null) { out.errors.push(`Line ${line}: unrecognised type "${get("type")}" (use buy, sell, income or transfer).`); continue; }
    const toWallet = map.toWallet === undefined ? "" : (r[map.toWallet] ?? "");
    if (kind === "transfer" && !toWallet) { out.skipped.push(`Line ${line}: transfer ignored (not a taxable event; add a "to wallet" column to move its lots in per-wallet mode).`); continue; }
    const date = parseDate(get("date"));
    if (!date) { out.errors.push(`Line ${line}: unreadable date "${get("date")}" (use YYYY-MM-DD or MM/DD/YYYY).`); continue; }
    const asset = get("asset").toUpperCase();
    if (!asset) { out.errors.push(`Line ${line}: missing asset.`); continue; }
    const qty = Math.abs(parseNumber(get("quantity")));
    if (!(qty > 0)) { out.errors.push(`Line ${line}: quantity must be a positive number.`); continue; }
    if (kind === "transfer") {
      const from = get("wallet");
      if (!from) { out.errors.push(`Line ${line}: a transfer needs a wallet to move the coins out of.`); continue; }
      if (from === toWallet) { out.skipped.push(`Line ${line}: transfer from and to the same wallet ignored.`); continue; }
      out.transactions.push({ line, date, kind, asset, qty, usd: 0, fee: 0, wallet: from, toWallet });
      continue;
    }
    const totalRaw = map.total === undefined ? null : parseNumber(get("total"));
    const priceRaw = map.price === undefined ? null : parseNumber(get("price"));
    let usd = totalRaw !== null && !Number.isNaN(totalRaw) ? Math.abs(totalRaw) : null;
    if (usd === null && priceRaw !== null && !Number.isNaN(priceRaw)) usd = Math.abs(priceRaw) * qty;
    if (usd === null) { out.errors.push(`Line ${line}: no USD total or price.`); continue; }
    const feeRaw = map.fee === undefined ? 0 : parseNumber(get("fee"));
    const fee = Number.isNaN(feeRaw) || feeRaw === null ? 0 : Math.abs(feeRaw);
    const wallet = get("wallet") || "";
    out.transactions.push({ line, date, kind, asset, qty, usd, fee, wallet });
  }
  return out;
}

// ---- lot matching ------------------------------------------------------

function addOneYear(iso) {
  const [y, m, d] = iso.split("-").map(Number);
  const dt = new Date(Date.UTC(y + 1, m - 1, d));
  // Feb 29 acquisition: Date rolls to Mar 1, which is the day after the anniversary.
  if (m === 2 && d === 29) return `${y + 1}-02-28`;
  return dt.toISOString().slice(0, 10);
}

// Long-term means held for MORE than one year: the sale date must fall after the
// first anniversary of the acquisition date.
export function holdingTerm(acquired, sold) {
  return sold > addOneYear(acquired) ? "Long" : "Short";
}

function rateOf(term, rates) {
  return term === "Long" ? rates.longRate : rates.shortRate;
}

function orderLots(lots, method, sale, unitProceeds, rates) {
  const byAcq = (a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : a.seq - b.seq);
  const unitBasis = (l) => l.basis / l.qtyOriginal;
  const arr = lots.slice();
  switch (method) {
    case "FIFO": return arr.sort(byAcq);
    case "LIFO": return arr.sort((a, b) => -byAcq(a, b));
    case "HIFO": return arr.sort((a, b) => unitBasis(b) - unitBasis(a) || byAcq(a, b));
    case "LOFO": return arr.sort((a, b) => unitBasis(a) - unitBasis(b) || byAcq(a, b));
    case "TAXMIN": {
      const tax = (l) => (unitProceeds - unitBasis(l)) * rateOf(holdingTerm(l.date, sale.date), rates);
      return arr.sort((a, b) => tax(a) - tax(b) || byAcq(a, b));
    }
    default: throw new Error(`Unknown method ${method}`);
  }
}

const PRIORITY = { buy: 0, income: 0, transfer: 1, sell: 2 };

// Runs one method over every transaction. Returns pieces (one per lot consumed)
// and the lots still open at the end.
export function matchLots(transactions, { method = "FIFO", perWallet = false, shortRate = 0.24, longRate = 0.15 } = {}) {
  const rates = { shortRate, longRate };
  const ordered = transactions
    .map((t, i) => ({ ...t, seq: i }))
    .sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : PRIORITY[a.kind] - PRIORITY[b.kind] || a.seq - b.seq));
  const books = new Map();
  const bookKey = (t) => `${t.asset}\u0000${perWallet ? t.wallet : ""}`;
  const pieces = [];
  const shortfalls = [];
  for (const t of ordered) {
    if (t.kind === "transfer") {
      // Moving coins between your own wallets is not a sale. With one pool there is nothing to move;
      // per wallet, the chosen lots keep their purchase date and basis in the new wallet.
      if (!perWallet) continue;
      const from = books.get(bookKey(t)) || [];
      const dest = bookKey({ asset: t.asset, wallet: t.toWallet });
      if (!books.has(dest)) books.set(dest, []);
      let left = t.qty;
      const order = method === "TAXMIN" ? "FIFO" : method;
      for (const lot of orderLots(from.filter((l) => l.qty > EPS), order, t, 0, rates)) {
        if (left <= EPS) break;
        const take = Math.min(lot.qty, left);
        const basis = (lot.basis / lot.qtyOriginal) * take;
        books.get(dest).push({ ...lot, wallet: t.toWallet, qty: take, qtyOriginal: take, basis });
        lot.qty -= take;
        left -= take;
      }
      if (left > EPS) shortfalls.push({ asset: t.asset, wallet: t.wallet, line: t.line, date: t.date, qty: left, transfer: true });
      continue;
    }
    const key = bookKey(t);
    if (!books.has(key)) books.set(key, []);
    const lots = books.get(key);
    if (t.kind === "buy" || t.kind === "income") {
      const basis = t.kind === "buy" ? t.usd + t.fee : t.usd;
      lots.push({ date: t.date, seq: t.seq, line: t.line, kind: t.kind, asset: t.asset, wallet: t.wallet, qty: t.qty, qtyOriginal: t.qty, basis });
      continue;
    }
    // sale: fee reduces proceeds
    const netProceeds = t.usd - t.fee;
    const unitProceeds = netProceeds / t.qty;
    let remaining = t.qty;
    const open = lots.filter((l) => l.qty > EPS);
    for (const lot of orderLots(open, method, t, unitProceeds, rates)) {
      if (remaining <= EPS) break;
      const take = Math.min(lot.qty, remaining);
      const share = take / t.qty;
      pieces.push({
        asset: t.asset, wallet: t.wallet, qty: take, saleLine: t.line, lotLine: lot.line,
        acquired: lot.date, sold: t.date,
        proceeds: netProceeds * share,
        basis: (lot.basis / lot.qtyOriginal) * take,
        term: holdingTerm(lot.date, t.date),
        missingBasis: false,
      });
      lot.qty -= take;
      remaining -= take;
    }
    if (remaining > EPS) {
      const share = remaining / t.qty;
      shortfalls.push({ asset: t.asset, wallet: t.wallet, line: t.line, date: t.date, qty: remaining });
      pieces.push({
        asset: t.asset, wallet: t.wallet, qty: remaining, saleLine: t.line, lotLine: null,
        acquired: null, sold: t.date, proceeds: netProceeds * share, basis: 0, term: "Short", missingBasis: true,
      });
    }
  }
  const openLots = [];
  for (const lots of books.values()) for (const l of lots) if (l.qty > EPS) openLots.push({ ...l });
  return { pieces, openLots, shortfalls };
}

// ---- reporting ---------------------------------------------------------

export function toRow(p) {
  const proceeds = cents(p.proceeds);
  const basis = cents(p.basis);
  return {
    description: `${trimQty(p.qty)} ${p.asset}`,
    asset: p.asset,
    wallet: p.wallet,
    acquired: p.acquired,
    sold: p.sold,
    proceeds,
    basis,
    gain: cents(proceeds - basis),
    term: p.term,
    missingBasis: p.missingBasis,
  };
}

function trimQty(q) {
  return String(Number(q.toFixed(8)));
}

export function summarize(rows) {
  const s = { shortGain: 0, longGain: 0, shortProceeds: 0, longProceeds: 0, shortBasis: 0, longBasis: 0 };
  for (const r of rows) {
    const k = r.term === "Long" ? "long" : "short";
    s[`${k}Gain`] += r.gain;
    s[`${k}Proceeds`] += r.proceeds;
    s[`${k}Basis`] += r.basis;
  }
  for (const k of Object.keys(s)) s[k] = cents(s[k]);
  s.totalGain = cents(s.shortGain + s.longGain);
  return s;
}

// Column totals for each part of Form 8949 (Part I short-term, Part II
// long-term) and the combined figure, the numbers that carry to Schedule D.
// Sums the already-rounded rows, so the totals equal what the rows add up to on
// paper. `noBasis` counts rows with no purchase on record, whose zero basis
// overstates the gain until the missing buy is added.
export function form8949Totals(rows) {
  const blank = () => ({ rows: 0, proceeds: 0, basis: 0, gain: 0, noBasis: 0 });
  const t = { short: blank(), long: blank() };
  for (const r of rows) {
    const part = t[r.term === "Long" ? "long" : "short"];
    part.rows += 1;
    part.proceeds += r.proceeds;
    part.basis += r.basis;
    part.gain += r.gain;
    if (r.missingBasis) part.noBasis += 1;
  }
  for (const part of [t.short, t.long]) {
    for (const k of ["proceeds", "basis", "gain"]) part[k] = cents(part[k]);
  }
  t.total = {
    rows: t.short.rows + t.long.rows,
    proceeds: cents(t.short.proceeds + t.long.proceeds),
    basis: cents(t.short.basis + t.long.basis),
    gain: cents(t.short.gain + t.long.gain),
    noBasis: t.short.noBasis + t.long.noBasis,
  };
  return t;
}

// Federal-style netting of short and long results, ignoring NIIT, the $3,000
// ordinary-income loss deduction and carryforwards. A net loss costs nothing here.
export function estimateTax(summary, { shortRate, longRate }) {
  const st = summary.shortGain;
  const lt = summary.longGain;
  let tax;
  if (st >= 0 && lt >= 0) tax = st * shortRate + lt * longRate;
  else if (st < 0 && lt > 0) tax = Math.max(0, lt + st) * longRate;
  else if (st > 0 && lt < 0) tax = Math.max(0, st + lt) * shortRate;
  else tax = 0;
  return cents(tax);
}

// Capital-loss netting with the $3,000 annual limit and indefinite carryforward
// (Schedule D and its Capital Loss Carryover Worksheet, simplified): short-term
// and long-term results net within their own bucket, then against each other; a
// net loss is deductible up to `limit` ($3,000, or $1,500 married filing
// separately) and the rest carries to next year keeping its character, with the
// deduction taken from the short-term loss first. Tax on a net gain uses the
// short and long rates on whatever remains of each bucket. Ignores NIIT, state
// tax and the effect of the deduction on ordinary tax (`deduction` is reported,
// not valued).
export function netCapital(shortGain, longGain, { carryShort = 0, carryLong = 0, limit = 3000, shortRate = 0.24, longRate = 0.15 } = {}) {
  const s = cents(shortGain - Math.abs(carryShort));
  const l = cents(longGain - Math.abs(carryLong));
  const total = cents(s + l);
  let deduction = 0, outShort = 0, outLong = 0, tax = 0;
  if (total < 0) {
    deduction = Math.min(limit, -total);
    const rest = cents(-total - deduction);
    if (s < 0 && l < 0) { outShort = Math.max(0, cents(-s - deduction)); outLong = cents(rest - outShort); }
    else if (s < 0) outShort = rest;
    else outLong = rest;
  } else if (s >= 0 && l >= 0) tax = s * shortRate + l * longRate;
  else if (s < 0) tax = total * longRate;
  else tax = total * shortRate;
  return { shortNet: s, longNet: l, totalNet: total, deduction: cents(deduction), carryShortOut: cents(outShort), carryLongOut: cents(outLong), tax: cents(tax) };
}

// Chains `netCapital` over several years: [{ year, shortGain, longGain }] in
// any order, years with no sales between them carry through unchanged.
export function carryoverChain(yearSummaries, opts = {}) {
  let carryShort = Math.abs(opts.carryShort || 0), carryLong = Math.abs(opts.carryLong || 0);
  const out = [];
  for (const y of [...yearSummaries].sort((a, b) => a.year - b.year)) {
    const r = netCapital(y.shortGain, y.longGain, { ...opts, carryShort, carryLong });
    out.push({ year: y.year, carryShortIn: cents(carryShort), carryLongIn: cents(carryLong), shortGain: y.shortGain, longGain: y.longGain, ...r });
    carryShort = r.carryShortOut; carryLong = r.carryLongOut;
  }
  return out;
}

export function yearOf(iso) {
  return Number(iso.slice(0, 4));
}

export function analyze(text, options = {}) {
  const { method = "FIFO", year = null, perWallet = false, shortRate = 0.24, longRate = 0.15, carryShort = 0, carryLong = 0, lossLimit = 3000 } = options;
  const parsed = parseTransactions(text);
  const result = {
    errors: parsed.errors, skipped: parsed.skipped, warnings: [], years: [], year: null,
    rows: [], summary: null, tax: null, netting: null, carryChain: [], comparison: [], holdings: [], openLots: [], income: 0, method, count: parsed.transactions.length,
  };
  if (parsed.errors.length && parsed.transactions.length === 0) return result;
  const txs = parsed.transactions;
  if (txs.length === 0) { result.errors.push("No transactions found."); return result; }

  const saleYears = [...new Set(txs.filter((t) => t.kind === "sell").map((t) => yearOf(t.date)))].sort();
  result.years = saleYears;
  const chosen = year ?? saleYears[saleYears.length - 1] ?? null;
  result.year = chosen;
  const rates = { shortRate, longRate };

  const run = (m) => {
    const { pieces, openLots, shortfalls } = matchLots(txs, { method: m, perWallet, shortRate, longRate });
    const rows = pieces.map(toRow).filter((r) => chosen === null || yearOf(r.sold) === chosen)
      .sort((a, b) => (a.sold < b.sold ? -1 : a.sold > b.sold ? 1 : (a.acquired || "") < (b.acquired || "") ? -1 : 1));
    const summary = summarize(rows);
    return { rows, summary, tax: estimateTax(summary, rates), openLots, shortfalls };
  };

  const main = run(method);
  result.rows = main.rows;
  result.summary = main.summary;
  result.tax = main.tax;
  for (const m of METHODS) {
    const r = m === method ? main : run(m);
    result.comparison.push({
      method: m, label: METHOD_LABELS[m], shortGain: r.summary.shortGain, longGain: r.summary.longGain,
      totalGain: r.summary.totalGain, tax: r.tax,
    });
  }
  {
    const { pieces } = matchLots(txs, { method, perWallet, shortRate, longRate });
    const byYear = new Map();
    for (const p of pieces) {
      const row = toRow(p), y = yearOf(row.sold);
      const a = byYear.get(y) || [];
      a.push(row);
      byYear.set(y, a);
    }
    const sums = [...byYear].map(([y, rs]) => { const sm = summarize(rs); return { year: y, shortGain: sm.shortGain, longGain: sm.longGain }; });
    result.carryChain = carryoverChain(sums, { carryShort, carryLong, limit: lossLimit, shortRate, longRate });
    result.netting = result.carryChain.find((c) => c.year === chosen) || null;
  }
  const best = result.comparison.reduce((a, b) => (b.tax < a.tax || (b.tax === a.tax && b.totalGain < a.totalGain) ? b : a));
  result.bestMethod = best.method;

  for (const s of main.shortfalls) {
    if (s.transfer) { result.warnings.push(`Line ${s.line} (${s.date}): transferred ${trimQty(s.qty)} ${s.asset} more than the lots on record in wallet "${s.wallet}". Only the coins on record were moved; add the missing buy, income or transfer-in history.`); continue; }
    result.warnings.push(`Line ${s.line} (${s.date}): sold ${trimQty(s.qty)} ${s.asset} more than the lots on record${perWallet && s.wallet ? ` in wallet "${s.wallet}"` : ""}. That part is shown with zero basis; add the missing buy, income or transfer-in history.`);
  }
  const holdings = new Map();
  for (const l of main.openLots) {
    const k = l.asset;
    const h = holdings.get(k) || { asset: k, qty: 0, basis: 0 };
    h.qty += l.qty;
    h.basis += (l.basis / l.qtyOriginal) * l.qty;
    holdings.set(k, h);
  }
  result.holdings = [...holdings.values()].map((h) => ({ asset: h.asset, qty: Number(h.qty.toFixed(8)), basis: cents(h.basis) })).sort((a, b) => b.basis - a.basis);
  result.openLots = main.openLots.map((l) => ({
    asset: l.asset, wallet: l.wallet, acquired: l.date, qty: Number(l.qty.toFixed(8)), basis: cents((l.basis / l.qtyOriginal) * l.qty),
  }));
  result.income = cents(txs.filter((t) => t.kind === "income" && (chosen === null || yearOf(t.date) === chosen)).reduce((a, t) => a + t.usd, 0));
  return result;
}

// "BTC=65000, ETH 3200" or one per line -> { BTC: 65000, ETH: 3200 }. Bad entries are reported, never guessed.
export function parsePrices(text) {
  const prices = {};
  const errors = [];
  for (const part of String(text || "").split(/[\n;]+|,(?=\s*[A-Za-z])/)) {
    const t = part.trim();
    if (!t) continue;
    const m = t.match(/^([A-Za-z0-9.\-]+)\s*[=:\s]\s*\$?\s*([0-9][0-9,]*(?:\.[0-9]+)?)$/);
    if (!m) { errors.push(`Could not read "${t}". Write it as BTC=65000.`); continue; }
    const v = Number(m[2].replace(/,/g, ""));
    if (!(v > 0)) { errors.push(`Price for ${m[1]} must be above zero.`); continue; }
    prices[m[1].toUpperCase()] = v;
  }
  return { prices, errors };
}

// Tax-loss harvesting view of the lots still open. For each lot with a price you
// typed: unrealized gain or loss and its term if sold on `asOf`. Then the tax
// saved by selling every losing lot against the year's realized result
// (`summary` from analyze, already net of the chosen method). Biggest tax saved
// per lot first. No wash-sale rule is applied; see the page for why that is a
// question of current law, not of arithmetic.
export function harvestPlan(openLots, prices, { asOf, summary = null, shortRate = 0.24, longRate = 0.15 } = {}) {
  const base = summary || { shortGain: 0, longGain: 0 };
  const lots = [];
  const unpriced = new Set();
  for (const l of openLots) {
    const price = prices[l.asset];
    if (!price) { unpriced.add(l.asset); continue; }
    const value = cents(l.qty * price);
    const gain = cents(value - l.basis);
    const term = holdingTerm(l.acquired, asOf);
    lots.push({ asset: l.asset, wallet: l.wallet, acquired: l.acquired, qty: l.qty, basis: l.basis, value, gain, term });
  }
  const losers = lots.filter((l) => l.gain < 0);
  const net = (extraShort, extraLong) => estimateTax({ shortGain: base.shortGain + extraShort, longGain: base.longGain + extraLong }, { shortRate, longRate });
  const shortLoss = cents(losers.filter((l) => l.term === "Short").reduce((a, l) => a + l.gain, 0));
  const longLoss = cents(losers.filter((l) => l.term === "Long").reduce((a, l) => a + l.gain, 0));
  const taxBefore = net(0, 0);
  const taxAfter = net(shortLoss, longLoss);
  // Standalone saving per lot (against the current result), for ranking only.
  for (const l of losers) l.taxSaved = cents(taxBefore - (l.term === "Short" ? net(l.gain, 0) : net(0, l.gain)));
  losers.sort((a, b) => b.taxSaved - a.taxSaved || a.gain - b.gain);
  return {
    asOf, lots, losers, unpriced: [...unpriced].sort(),
    unrealizedGain: cents(lots.reduce((a, l) => a + l.gain, 0)),
    shortLoss, longLoss, taxBefore, taxAfter, taxSaved: cents(taxBefore - taxAfter),
    unusedLoss: cents(Math.max(0, -(base.shortGain + shortLoss + base.longGain + longLoss))),
  };
}

const q = (v) => {
  const s = v === null || v === undefined ? "" : String(v);
  return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};

// CSV in Form 8949 column order, ready to paste into tax software or hand to a preparer.
export function toForm8949Csv(rows) {
  const head = ["Description of property", "Date acquired", "Date sold", "Proceeds", "Cost or other basis", "Gain or loss", "Term", "Note"];
  const lines = [head.join(",")];
  for (const r of rows) {
    lines.push([
      r.description, r.acquired || "VARIOUS", r.sold, r.proceeds.toFixed(2), r.basis.toFixed(2), r.gain.toFixed(2), r.term,
      r.missingBasis ? "No basis on record" : "",
    ].map(q).join(","));
  }
  return lines.join("\n") + "\n";
}

export const SAMPLE_CSV = `date,type,asset,quantity,total,fee,wallet
2023-01-10,buy,BTC,0.50,10000,10,Exchange A
2023-06-15,buy,BTC,0.50,15000,15,Exchange A
2024-02-01,buy,BTC,0.25,12000,12,Exchange A
2024-03-05,income,ETH,2,5000,0,Exchange A
2024-09-20,sell,BTC,0.60,36000,36,Exchange A
2024-11-02,sell,ETH,1,3300,3,Exchange A
`;

cli.mjs.text:
#!/usr/bin/env node
// Match crypto sales to purchase lots from exchange CSVs, in a terminal.
//
//   node cli.mjs coinbase.csv                       # FIFO summary for the latest sale year
//   node cli.mjs --method HIFO --year 2024 a.csv b.csv
//   node cli.mjs --form8949 8949.csv kraken.csv      # write Form 8949 style rows
//   node cli.mjs --json coinbase.csv                 # machine-readable
//   cat history.csv | node cli.mjs -                 # read stdin
//   node cli.mjs --example                           # built-in sample
//
// Zero dependencies, no network: files are read locally and nothing is sent.
// Same matching as the web page (calc.mjs) and the same exchange readers
// (importers.mjs), so the numbers agree with the page.

import { readFile, writeFile } from "node:fs/promises";
import process from "node:process";
import { analyze, toForm8949Csv, form8949Totals, METHODS, METHOD_LABELS, SAMPLE_CSV } from "./calc.mjs";
import { convertMany, FORMAT_LABELS } from "./importers.mjs";

const USAGE = `Crypto cost basis from exchange CSVs: lot matching, method comparison, Form 8949 style rows.

Usage:
  node cli.mjs [options] <file.csv ...| ->

Options:
  --method <m>        FIFO (default), LIFO, HIFO, LOFO or TAXMIN
  --year <yyyy>       tax year of the sales (default: the latest year with a sale)
  --per-wallet        match each sale only against lots in the same wallet
  --carry-short <usd>  short-term loss carried in from before the file starts
  --carry-long <usd>   long-term loss carried in from before the file starts
  --mfs                $1,500 annual loss deduction (married filing separately)
  --short-rate <pct>  short-term rate for the tax estimate (default 24)
  --long-rate <pct>   long-term rate for the tax estimate (default 15)
  --form8949 <file>   also write Form 8949 style rows to this file
  --json              print the full analysis as JSON
  --example           use the built-in sample instead of a file
  -h, --help          this message

Reads Coinbase, Kraken, Binance.US, Crypto.com App, Gemini and Bitstamp exports or the
plain CSV (date,type,asset,quantity,total,fee,wallet). Several files are
merged. Arithmetic on the figures in your files, not tax advice: it fetches no
prices, and rows an export gives no USD value for are flagged, never zero.
`;

export function parseArgs(argv) {
  const opts = { files: [], method: "FIFO", year: null, perWallet: false, shortRate: 0.24, longRate: 0.15, form8949: null, carryShort: 0, carryLong: 0, lossLimit: 3000, json: false, example: false, help: false };
  const need = (i, arg) => { if (i >= argv.length) throw new Error(`${arg} needs a value`); return argv[i]; };
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === "-h" || arg === "--help") opts.help = true;
    else if (arg === "--json") opts.json = true;
    else if (arg === "--example") opts.example = true;
    else if (arg === "--per-wallet") opts.perWallet = true;
    else if (arg === "--method") {
      const m = need(++i, arg).toUpperCase();
      if (!METHODS.includes(m)) throw new Error(`--method must be one of ${METHODS.join(", ")}`);
      opts.method = m;
    } else if (arg === "--year") {
      const y = Number(need(++i, arg));
      if (!Number.isInteger(y) || y < 2009 || y > 2100) throw new Error("--year needs a four-digit year");
      opts.year = y;
    } else if (arg === "--short-rate" || arg === "--long-rate") {
      const v = Number(need(++i, arg));
      if (!Number.isFinite(v) || v < 0 || v > 100) throw new Error(`${arg} needs a percent between 0 and 100`);
      opts[arg === "--short-rate" ? "shortRate" : "longRate"] = v / 100;
    } else if (arg === "--carry-short" || arg === "--carry-long") {
      const v = Number(need(++i, arg));
      if (!Number.isFinite(v) || v < 0) throw new Error(`${arg} needs a positive dollar amount`);
      opts[arg === "--carry-short" ? "carryShort" : "carryLong"] = v;
    } else if (arg === "--mfs") opts.lossLimit = 1500;
    else if (arg === "--form8949") opts.form8949 = need(++i, arg);
    else if (arg.startsWith("-") && arg !== "-") throw new Error(`unknown option: ${arg}`);
    else opts.files.push(arg);
  }
  return opts;
}

const usd = (n) => (n < 0 ? "-$" : "$") + Math.abs(n).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

// files: [{ name, text }]. Returns { result, formats, notes, csv, error }.
export function run(files, opts = {}) {
  const { formats, csv, notes } = convertMany(files);
  const result = analyze(csv, { method: opts.method || "FIFO", year: opts.year ?? null, perWallet: !!opts.perWallet, shortRate: opts.shortRate ?? 0.24, longRate: opts.longRate ?? 0.15, carryShort: opts.carryShort || 0, carryLong: opts.carryLong || 0, lossLimit: opts.lossLimit || 3000 });
  const error = result.errors.length && result.rows.length === 0 ? result.errors.join("; ") : null;
  return { result, formats, notes, csv, error };
}

export function render({ result, formats, notes }, opts = {}) {
  const out = [];
  out.push(`Read ${result.count} transactions (${[...new Set(formats)].map((f) => FORMAT_LABELS[f] || f).join(", ")}).`);
  for (const n of notes) out.push(`  note: ${n}`);
  for (const e of result.errors) out.push(`  problem: ${e}`);
  for (const s of result.skipped || []) out.push(`  skipped: ${typeof s === "string" ? s : JSON.stringify(s)}`);
  if (result.year === null) { out.push("No sales found, so there is nothing to match."); return out.join("\n") + "\n"; }
  const s = result.summary, t = totalsLine(result);
  out.push("", `Sales in ${result.year}, ${METHOD_LABELS[result.method]}${opts.perWallet ? ", per wallet" : ""}`);
  out.push(`  short-term ${usd(s.shortGain)}   long-term ${usd(s.longGain)}   total ${usd(s.totalGain)}   income received ${usd(result.income)}`);
  out.push(`  estimated tax ${usd(result.tax)} at ${(opts.shortRate ?? 0.24) * 100}% short / ${(opts.longRate ?? 0.15) * 100}% long`);
  if (t) out.push(`  ${t}`);
  if (result.carryChain.length) {
    out.push("", `Loss limit and carryforward (${usd(opts.lossLimit || 3000)} a year; years chained from the first sale in the file):`);
    for (const c of result.carryChain) out.push(`  ${c.year}  carried in ${usd(c.carryShortIn + c.carryLongIn).padStart(12)}   net ${usd(c.totalNet).padStart(13)}   deductible ${usd(c.deduction).padStart(10)}   carried out ${usd(c.carryShortOut + c.carryLongOut).padStart(12)}   tax ${usd(c.tax).padStart(11)}${c.year === result.year ? "   <- shown year" : ""}`);
  }
  out.push("", "Method comparison (same sales):");
  for (const c of result.comparison) out.push(`  ${c.label.padEnd(24)} gain ${usd(c.totalGain).padStart(14)}   tax ${usd(c.tax).padStart(12)}${c.method === result.bestMethod ? "   <- lowest estimated tax" : ""}`);
  if (result.holdings.length) {
    out.push("", "Still held:");
    for (const h of result.holdings) out.push(`  ${h.asset.padEnd(8)} ${String(h.qty).padStart(14)}   basis ${usd(h.basis)}`);
  }
  for (const w of result.warnings) out.push("", `warning: ${w}`);
  return out.join("\n") + "\n";
}

function totalsLine(result) {
  const f = form8949Totals(result.rows);
  return f.total.noBasis ? `${f.total.noBasis} row(s) have no purchase on record (zero basis); fix before filing.` : "";
}

async function readInput(name) {
  if (name === "-") {
    const chunks = [];
    for await (const c of process.stdin) chunks.push(c);
    return { name: "stdin", text: Buffer.concat(chunks).toString("utf8") };
  }
  return { name, text: await readFile(name, "utf8") };
}

export async function main(argv) {
  let opts;
  try { opts = parseArgs(argv); } catch (e) { process.stderr.write(`${e.message}\n\n${USAGE}`); return 2; }
  if (opts.help || (!opts.files.length && !opts.example)) { process.stdout.write(USAGE); return opts.help ? 0 : 2; }
  let files;
  try { files = opts.example ? [{ name: "example", text: SAMPLE_CSV }] : await Promise.all(opts.files.map(readInput)); }
  catch (e) { process.stderr.write(`cannot read input: ${e.message}\n`); return 2; }
  const r = run(files, opts);
  if (r.error) { process.stderr.write(`${r.error}\n`); return 1; }
  if (opts.form8949) await writeFile(opts.form8949, toForm8949Csv(r.result.rows));
  process.stdout.write(opts.json ? JSON.stringify(r.result, null, 2) + "\n" : render(r, opts));
  return 0;
}

if (import.meta.url === `file://${process.argv[1]}`) process.exitCode = await main(process.argv.slice(2));

importers.mjs.text:
// Exchange-export importers. Pure functions, no I/O, no dependencies.
//
// Turns a raw export from an exchange into the plain CSV that calc.mjs reads
// (date,type,asset,quantity,total,fee,wallet), so a person can drop in the file
// they already have instead of reshaping it by hand. Nothing is priced or
// fetched: a row whose USD value the export does not carry (a coin-for-coin
// trade on Kraken, a staking reward) is written with an empty `total` and
// reported in `notes`, so it shows up as a line to fill in rather than as a
// silent zero.
//
// Formats are written from the column layouts the exchanges publish and have
// not been checked against a real account; the notes say so where it matters.

import { parseCsv } from "./calc.mjs";

const norm = (s) => String(s).toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
const num = (raw) => {
  const s = String(raw ?? "").replace(/[$,\s]/g, "").replace(/^\((.*)\)$/, "-$1");
  if (s === "") return null;
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
};
const cell = (v) => (/[",\n\r]/.test(v) ? `"${String(v).replace(/"/g, '""')}"` : String(v));
const fmt = (n) => (n === null || n === undefined ? "" : String(+Number(n).toFixed(10)));

export const OUT_HEADER = "date,type,asset,quantity,total,fee,wallet";
const toCsv = (rows) => [OUT_HEADER, ...rows.map((r) => r.map(cell).join(","))].join("\n") + "\n";

// ---- format detection ----------------------------------------------------

function findHeader(grid, needles) {
  for (let i = 0; i < Math.min(grid.length, 30); i++) {
    const names = grid[i].map(norm);
    if (needles.every((n) => names.includes(n))) return i;
  }
  return -1;
}

export function detectFormat(text) {
  const grid = parseCsv(text);
  if (findHeader(grid, ["timestamp utc", "transaction kind", "native amount in usd"]) >= 0) return "cryptocom";
  if (findHeader(grid, ["date", "time utc", "type", "symbol", "usd amount usd"]) >= 0) return "gemini";
  if (findHeader(grid, ["timestamp", "transaction type", "asset"]) >= 0) return "coinbase";
  if (findHeader(grid, ["txid", "refid", "time", "type", "asset", "amount", "fee"]) >= 0) return "kraken";
  if (findHeader(grid, ["time", "operation", "primary asset"]) >= 0) return "binanceus";
  if (findHeader(grid, ["type", "datetime", "account", "amount", "value", "rate", "fee", "sub type"]) >= 0) return "bitstamp";
  return "generic";
}

// ---- Coinbase ------------------------------------------------------------

const CB_BUY = ["buy", "advanced trade buy"];
const CB_SELL = ["sell", "advanced trade sell"];
const CB_INCOME = ["rewards income", "staking income", "coinbase earn", "learning reward", "inflation reward", "reward income", "airdrop"];
const CB_MOVE = ["send", "receive", "deposit", "withdrawal"];

function importCoinbase(grid) {
  const h = findHeader(grid, ["timestamp", "transaction type", "asset"]);
  const names = grid[h].map(norm);
  const col = (...opts) => { for (const o of opts) { const i = names.indexOf(o); if (i >= 0) return i; } return -1; };
  const c = {
    ts: col("timestamp"), type: col("transaction type"), asset: col("asset"),
    qty: col("quantity transacted"), cur: col("spot price currency"),
    sub: col("subtotal", "usd subtotal"), total: col("total inclusive of fees and or spread", "total inclusive of fees", "usd total inclusive of fees"),
    fee: col("fees and or spread", "usd fees", "fees"), notes: col("notes"),
  };
  const out = [], notes = [];
  let sends = 0;
  for (let i = h + 1; i < grid.length; i++) {
    const r = grid[i];
    const g = (k) => (c[k] < 0 ? "" : r[c[k]] ?? "");
    const type = norm(g("type"));
    if (!type || !g("ts")) continue;
    const date = g("ts").slice(0, 10);
    const asset = g("asset").toUpperCase();
    const qty = Math.abs(num(g("qty")) ?? 0);
    const cur = g("cur").toUpperCase();
    if (cur && cur !== "USD") { notes.push(`Line ${i + 1}: priced in ${cur}, not USD, so it was skipped.`); continue; }
    const fee = Math.abs(num(g("fee")) ?? 0);
    const sub = num(g("sub"));
    const total = num(g("total"));
    // Subtotal is the value before fees; fall back to total minus fee on a buy.
    const usd = sub !== null ? Math.abs(sub) : total !== null ? Math.abs(total) : null;
    if (CB_BUY.includes(type)) out.push([date, "buy", asset, fmt(qty), fmt(usd), fmt(fee), "Coinbase"]);
    else if (CB_SELL.includes(type)) out.push([date, "sell", asset, fmt(qty), fmt(usd), fmt(fee), "Coinbase"]);
    else if (CB_INCOME.includes(type)) out.push([date, "income", asset, fmt(qty), fmt(usd), "0", "Coinbase"]);
    else if (type === "convert") {
      const m = g("notes").match(/converted\s+([\d.,]+)\s+(\S+)\s+to\s+([\d.,]+)\s+(\S+)/i);
      if (!m) { notes.push(`Line ${i + 1}: a Convert row whose Notes could not be read, so it was skipped. Enter it as a sale and a buy.`); continue; }
      const [, q1, a1, q2, a2] = m;
      out.push([date, "sell", a1.toUpperCase(), fmt(num(q1)), fmt(usd), fmt(fee), "Coinbase"]);
      out.push([date, "buy", a2.toUpperCase(), fmt(num(q2)), fmt(usd), "0", "Coinbase"]);
    } else if (CB_MOVE.includes(type)) {
      if (type === "send") sends++;
    } else notes.push(`Line ${i + 1}: unknown Coinbase type "${g("type")}", so it was skipped.`);
  }
  if (sends) notes.push(`${sends} Send row${sends > 1 ? "s" : ""} treated as transfers between your own wallets (not taxable). If any was a payment or a gift, enter it as a sale at its USD value.`);
  return { format: "coinbase", rows: out, notes };
}

// ---- Kraken (ledgers.csv) -------------------------------------------------

const OTHER_FIAT = new Set(["EUR", "GBP", "CAD", "AUD", "JPY", "CHF"]);
const STABLE = new Set(["USDT", "USDC", "DAI"]);
const ALIAS = { XBT: "BTC", XXBT: "BTC", XETH: "ETH", XXDG: "DOGE", XDG: "DOGE", XLTC: "LTC", XXRP: "XRP", XXLM: "XLM", XETC: "ETC", XXMR: "XMR", XZEC: "ZEC", ETH2: "ETH" };

export function krakenAsset(raw) {
  let a = String(raw).toUpperCase().replace(/\.(S|M|F|B|P)$/, "").replace(/\.(S|M|F|B|P)$/, "");
  if (ALIAS[a]) return ALIAS[a];
  if (a.length === 4 && a[0] === "Z" && (a === "ZUSD" || OTHER_FIAT.has(a.slice(1)))) return a.slice(1);
  return a;
}

function importKraken(grid) {
  const h = findHeader(grid, ["txid", "refid", "time", "type", "asset", "amount", "fee"]);
  const names = grid[h].map(norm);
  const ix = (n) => names.indexOf(n);
  const c = { refid: ix("refid"), time: ix("time"), type: ix("type"), sub: ix("subtype"), asset: ix("asset"), amount: ix("amount"), fee: ix("fee") };
  const out = [], notes = [];
  const trades = new Map();
  let staking = 0, fiatOther = 0, moves = 0;
  for (let i = h + 1; i < grid.length; i++) {
    const r = grid[i];
    const type = norm(r[c.type] ?? "");
    const asset = krakenAsset(r[c.asset] ?? "");
    const amount = num(r[c.amount]);
    const fee = num(r[c.fee]) ?? 0;
    const date = String(r[c.time] ?? "").slice(0, 10);
    if (!type || amount === null) continue;
    if (["trade", "spend", "receive"].includes(type)) {
      const k = r[c.refid];
      if (!trades.has(k)) trades.set(k, { date, legs: [] });
      trades.get(k).legs.push({ asset, amount, fee });
    } else if (type === "staking" || (type === "earn" && norm(r[c.sub] ?? "") === "reward")) {
      staking++;
      if (amount > 0) out.push([date, "income", asset, fmt(amount - fee), "", "0", "Kraken"]);
    } else if (["deposit", "withdrawal", "transfer", "margin", "rollover", "settled", "adjustment", "earn", "sale", "dividend"].includes(type)) {
      moves++;
    } else notes.push(`Line ${i + 1}: Kraken type "${r[c.type]}" was skipped.`);
  }
  for (const { date, legs } of trades.values()) {
    const usd = legs.find((l) => l.asset === "USD");
    const crypto = legs.filter((l) => l.asset !== "USD");
    if (crypto.some((l) => OTHER_FIAT.has(l.asset))) { fiatOther++; continue; }
    if (usd && crypto.length === 1) {
      const x = crypto[0];
      const total = Math.abs(usd.amount);
      if (x.amount > 0) out.push([date, "buy", x.asset, fmt(x.amount - x.fee), fmt(total), fmt(usd.fee), "Kraken"]);
      else out.push([date, "sell", x.asset, fmt(Math.abs(x.amount) + x.fee), fmt(total), fmt(usd.fee), "Kraken"]);
    } else if (crypto.length === 2) {
      const [a, b] = crypto[0].amount < 0 ? crypto : [crypto[1], crypto[0]];
      const st = [a, b].find((l) => STABLE.has(l.asset));
      const known = st ? fmt(Math.abs(st.amount)) : ""; // a stablecoin leg is a USD figure the export does carry
      out.push([date, "sell", a.asset, fmt(Math.abs(a.amount) + a.fee), known, "0", "Kraken"]);
      out.push([date, "buy", b.asset, fmt(b.amount - b.fee), known, "0", "Kraken"]);
      if (!st) notes.push(`${date}: ${a.asset} to ${b.asset} swap has no USD value in the export. Fill in the empty total on its two rows.`);
      else notes.push(`${date}: ${a.asset} to ${b.asset} swap priced from the ${st.asset} leg at $1 per coin; check it against the day's price if the stablecoin was off its peg.`);
    } else notes.push(`${date}: a Kraken trade with ${legs.length} legs could not be read, so it was skipped.`);
  }
  if (staking) notes.push(`${staking} staking reward row${staking > 1 ? "s" : ""} imported as income with an empty USD total. Fill in each reward's USD value on the day received.`);
  if (fiatOther) notes.push(`${fiatOther} trade${fiatOther > 1 ? "s" : ""} against a non-USD currency skipped; enter them with a USD value.`);
  if (moves) notes.push(`${moves} deposit, withdrawal and transfer rows ignored as non-taxable movements.`);
  out.sort((x, y) => (x[0] < y[0] ? -1 : x[0] > y[0] ? 1 : 0));
  return { format: "kraken", rows: out, notes };
}

// ---- Binance.US (transaction history) --------------------------------------

const BN_INCOME = /reward|distribution|airdrop|referral|cashback|interest/;
const BN_MOVE = /deposit|withdraw|transfer|stake|unstake|subscri|redeem/;

function importBinanceUs(grid) {
  const h = findHeader(grid, ["time", "operation", "primary asset"]);
  const names = grid[h].map(norm);
  const ix = (n) => names.indexOf(n);
  const c = {
    time: ix("time"), cat: ix("category"), op: ix("operation"), asset: ix("primary asset"),
    qty: ix("realized amount for primary asset"), usd: ix("realized amount for primary asset in usd value"),
    qusd: ix("realized amount for quote asset in usd value"), fusd: ix("realized amount for fee asset in usd value"),
  };
  const out = [], notes = [];
  let moves = 0, unpriced = 0;
  for (let i = h + 1; i < grid.length; i++) {
    const r = grid[i];
    const g = (k) => (c[k] < 0 ? "" : r[c[k]] ?? "");
    const op = norm(g("op"));
    if (!op || !g("time")) continue;
    const date = g("time").slice(0, 10);
    const asset = g("asset").toUpperCase();
    const qty = Math.abs(num(g("qty")) ?? 0);
    const usd = num(g("usd")) ?? num(g("qusd"));
    const total = usd === null ? null : Math.abs(usd);
    const fee = Math.abs(num(g("fusd")) ?? 0);
    if (/^buy\b/.test(op) || /^sell\b/.test(op)) {
      if (total === null) unpriced++;
      out.push([date, op.startsWith("buy") ? "buy" : "sell", asset, fmt(qty), fmt(total), fmt(fee), "Binance.US"]);
    } else if (BN_INCOME.test(op) || BN_INCOME.test(norm(g("cat")))) {
      if (total === null) unpriced++;
      out.push([date, "income", asset, fmt(qty), fmt(total), "0", "Binance.US"]);
    } else if (BN_MOVE.test(op)) moves++;
    else notes.push(`Line ${i + 1}: Binance.US operation "${g("op")}" was skipped.`);
  }
  if (unpriced) notes.push(`${unpriced} Binance.US row${unpriced > 1 ? "s" : ""} had no USD value in the export and were left with an empty total. Fill each in from that day's price.`);
  if (moves) notes.push(`${moves} deposit, withdrawal and staking-transfer rows ignored as non-taxable movements.`);
  return { format: "binanceus", rows: out, notes };
}

// ---- Crypto.com App (transaction history) ----------------------------------

const CDC_BUY = /purchase|buy/;
const CDC_SELL = /viban_exchange|sell|crypto_to_fiat/;
const CDC_SWAP = /crypto_exchange|dust_conversion|swap|convert/;
const CDC_INCOME = /reward|interest|cashback|referral|airdrop|rebate|bonus/;
const CDC_MOVE = /deposit|withdraw|transfer|lockup|stake|lock|card_top_up|admin/;

function importCryptoCom(grid) {
  const h = findHeader(grid, ["timestamp utc", "transaction kind", "native amount in usd"]);
  const names = grid[h].map(norm);
  const ix = (n) => names.indexOf(n);
  const c = {
    ts: ix("timestamp utc"), cur: ix("currency"), amt: ix("amount"), toCur: ix("to currency"), toAmt: ix("to amount"),
    usd: ix("native amount in usd"), kind: ix("transaction kind"),
  };
  const out = [], notes = [];
  let moves = 0, unpriced = 0;
  for (let i = h + 1; i < grid.length; i++) {
    const r = grid[i];
    const g = (k) => (c[k] < 0 ? "" : r[c[k]] ?? "");
    const kind = String(g("kind")).toLowerCase().trim();
    if (!kind || !g("ts")) continue;
    const date = g("ts").slice(0, 10);
    const cur = g("cur").toUpperCase();
    const qty = Math.abs(num(g("amt")) ?? 0);
    const usd = num(g("usd"));
    const total = usd === null ? null : Math.abs(usd);
    const row = (type, asset, q) => {
      if (total === null) unpriced++;
      out.push([date, type, asset, fmt(q), fmt(total), "0", "Crypto.com"]);
    };
    if (CDC_SELL.test(kind)) row("sell", cur, qty);
    else if (CDC_BUY.test(kind)) row("buy", cur, qty);
    else if (CDC_SWAP.test(kind) && g("toCur")) {
      row("sell", cur, qty);
      row("buy", g("toCur").toUpperCase(), Math.abs(num(g("toAmt")) ?? 0));
    } else if (CDC_INCOME.test(kind) && (num(g("amt")) ?? 0) > 0) row("income", cur, qty);
    else if (CDC_MOVE.test(kind)) moves++;
    else notes.push(`Line ${i + 1}: Crypto.com transaction kind "${g("kind")}" was skipped.`);
  }
  if (unpriced) notes.push(`${unpriced} Crypto.com row${unpriced > 1 ? "s" : ""} had no USD value in the export and were left with an empty total. Fill each in from that day's price.`);
  if (moves) notes.push(`${moves} deposit, withdrawal, transfer and staking-lock rows ignored as non-taxable movements. A withdrawal that paid someone is a sale; enter it by hand.`);
  notes.push("The export has no fee column, so fees are 0; the Native Amount (in USD) on App trades already includes the spread.");
  out.sort((x, y) => (x[0] < y[0] ? -1 : x[0] > y[0] ? 1 : 0));
  return { format: "cryptocom", rows: out, notes };
}

// ---- Gemini (transaction history) -----------------------------------------

const GEM_INCOME = /interest|reward|earn|staking|airdrop|bonus|rebate/;
const GEM_MOVE = /credit|debit|deposit|withdraw|transfer/;
// Gemini writes amounts as "$1,000.00", "(100.00)" or "0.01 BTC".
const gemNum = (raw) => num(String(raw ?? "").replace(/[A-Za-z]+/g, ""));

function importGemini(grid) {
  const h = findHeader(grid, ["date", "time utc", "type", "symbol", "usd amount usd"]);
  const names = grid[h].map(norm);
  const ix = (n) => names.indexOf(n);
  const c = { date: ix("date"), type: ix("type"), sym: ix("symbol"), usd: ix("usd amount usd"), fee: ix("trading fee usd usd") };
  const out = [], notes = [];
  let moves = 0, unpriced = 0;
  for (let i = h + 1; i < grid.length; i++) {
    const r = grid[i];
    const g = (k) => (c[k] < 0 ? "" : r[c[k]] ?? "");
    const type = norm(g("type"));
    if (!type || !g("date")) continue;
    const date = g("date").slice(0, 10);
    const sym = g("sym").toUpperCase().trim();
    if (type === "buy" || type === "sell") {
      const base = sym.endsWith("USD") ? sym.slice(0, -3) : "";
      const qcol = base ? ix(`${base.toLowerCase()} amount ${base.toLowerCase()}`) : -1;
      const qty = qcol < 0 ? null : Math.abs(gemNum(r[qcol]) ?? 0);
      if (!base || qty === null) {
        notes.push(`Line ${i + 1}: Gemini ${type} of "${g("sym")}" was skipped (only USD pairs with a matching amount column are read).`);
        continue;
      }
      const usd = gemNum(g("usd"));
      const total = usd === null ? null : Math.abs(usd);
      if (total === null) unpriced++;
      out.push([date, type, base, fmt(qty), fmt(total), fmt(Math.abs(gemNum(g("fee")) ?? 0)), "Gemini"]);
    } else if (GEM_INCOME.test(type)) {
      const col = ix(`${sym.toLowerCase()} amount ${sym.toLowerCase()}`);
      const qty = col < 0 ? null : Math.abs(gemNum(r[col]) ?? 0);
      if (!sym || qty === null) { notes.push(`Line ${i + 1}: Gemini "${g("type")}" for "${g("sym")}" was skipped.`); continue; }
      unpriced++;
      out.push([date, "income", sym, fmt(qty), "", "0", "Gemini"]);
    } else if (GEM_MOVE.test(type)) moves++;
    else notes.push(`Line ${i + 1}: Gemini transaction type "${g("type")}" was skipped.`);
  }
  if (unpriced) notes.push(`${unpriced} Gemini row${unpriced > 1 ? "s" : ""} had no USD value in the export and were left with an empty total. Fill each in from that day's price.`);
  if (moves) notes.push(`${moves} credit, debit, deposit and withdrawal rows ignored as non-taxable movements. A withdrawal that paid someone is a sale; enter it by hand.`);
  return { format: "gemini", rows: out, notes };
}

// ---- Bitstamp ------------------------------------------------------------
//
// Bitstamp's transaction export is one row per trade with the amounts spelled
// as "0.5 BTC" / "10000 USD" and a date such as "Jan. 10, 2023, 10:00 AM".
// Only USD-valued Market buys and sells are read; a trade valued in another
// currency is skipped with a note rather than converted at a rate nobody typed.

const MONTHS = { jan: "01", feb: "02", mar: "03", apr: "04", may: "05", jun: "06", jul: "07", aug: "08", sep: "09", oct: "10", nov: "11", dec: "12" };
function bitstampDate(raw) {
  const s = String(raw ?? "").trim();
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
  const m = s.match(/^([A-Za-z]{3})[a-z]*\.?\s+(\d{1,2}),\s*(\d{4})/);
  return m && MONTHS[m[1].toLowerCase()] ? `${m[3]}-${MONTHS[m[1].toLowerCase()]}-${m[2].padStart(2, "0")}` : "";
}
// "0.5 BTC" -> { n: 0.5, cur: "BTC" }
const bitstampAmount = (raw) => {
  const m = String(raw ?? "").trim().match(/^(.*?)\s*([A-Za-z]{2,10})$/);
  return m ? { n: num(m[1]), cur: m[2].toUpperCase() } : { n: num(raw), cur: "" };
};

function importBitstamp(grid) {
  const h = findHeader(grid, ["type", "datetime", "account", "amount", "value", "rate", "fee", "sub type"]);
  const names = grid[h].map(norm);
  const c = { type: names.indexOf("type"), date: names.indexOf("datetime"), amount: names.indexOf("amount"), value: names.indexOf("value"), fee: names.indexOf("fee"), sub: names.indexOf("sub type") };
  const out = [], notes = [];
  let moves = 0;
  for (let i = h + 1; i < grid.length; i++) {
    const r = grid[i];
    const type = norm(r[c.type] ?? "");
    if (!type) continue;
    if (type !== "market") {
      if (/deposit|withdrawal|sub account transfer/.test(type)) moves++;
      else notes.push(`Line ${i + 1}: Bitstamp row type "${r[c.type]}" was skipped.`);
      continue;
    }
    const side = norm(r[c.sub] ?? "");
    const date = bitstampDate(r[c.date]);
    const amt = bitstampAmount(r[c.amount]);
    const val = bitstampAmount(r[c.value]);
    const fee = bitstampAmount(r[c.fee]);
    if ((side !== "buy" && side !== "sell") || !date || amt.n === null || !amt.cur) {
      notes.push(`Line ${i + 1}: Bitstamp ${side || "trade"} could not be read and was skipped.`);
      continue;
    }
    if (val.cur !== "USD") {
      notes.push(`Line ${i + 1}: Bitstamp ${side} of ${amt.cur} is valued in ${val.cur || "an unknown currency"}, not USD, and was skipped. Enter it by hand at that day's USD value.`);
      continue;
    }
    out.push([date, side, amt.cur, fmt(Math.abs(amt.n)), fmt(val.n === null ? null : Math.abs(val.n)), fmt(fee.cur === "USD" && fee.n !== null ? Math.abs(fee.n) : 0), "Bitstamp"]);
    if (fee.n && fee.cur !== "USD") notes.push(`Line ${i + 1}: Bitstamp fee in ${fee.cur || "another currency"} was not counted; add it to the fee by hand.`);
  }
  if (moves) notes.push(`${moves} deposit and withdrawal rows ignored as non-taxable movements. A withdrawal that paid someone is a sale; enter it by hand.`);
  return { format: "bitstamp", rows: out, notes };
}

// ---- entry points ---------------------------------------------------------

export const FORMAT_LABELS = { coinbase: "Coinbase transaction history", kraken: "Kraken ledger", binanceus: "Binance.US transaction history", cryptocom: "Crypto.com App transaction history", gemini: "Gemini transaction history", bitstamp: "Bitstamp transaction export", generic: "plain CSV" };

// Returns { format, csv, notes }. A generic file comes back unchanged.
export function convertExchangeCsv(text) {
  const format = detectFormat(text);
  if (format === "generic") return { format, csv: String(text ?? ""), notes: [] };
  const grid = parseCsv(text);
  const r = format === "coinbase" ? importCoinbase(grid) : format === "binanceus" ? importBinanceUs(grid) : format === "cryptocom" ? importCryptoCom(grid) : format === "gemini" ? importGemini(grid) : format === "bitstamp" ? importBitstamp(grid) : importKraken(grid);
  return { format, csv: toCsv(r.rows), notes: r.notes, count: r.rows.length };
}

// Several files at once (e.g. two exchanges, or one per year): one CSV, one header.
export function convertMany(files) {
  const lines = [], notes = [], formats = [];
  for (const f of files) {
    const r = convertExchangeCsv(f.text);
    formats.push(r.format);
    for (const n of r.notes) notes.push(files.length > 1 ? `${f.name}: ${n}` : n);
    const body = r.csv.split(/\r?\n/);
    if (lines.length === 0) lines.push(...body.filter((l) => l.trim()));
    else {
      if (r.format === "generic" && norm(body[0]) !== norm(OUT_HEADER)) notes.push(`${f.name}: header differs from the first file's; check that the columns line up.`);
      lines.push(...body.slice(1).filter((l) => l.trim()));
    }
  }
  return { formats, csv: lines.join("\n") + "\n", notes };
}

